use crate::feagi_id::feagi_id::FeagiID;
use thiserror::Error;

/// A [`FeagiID`] that holds a UUID of a single version. Generated by `feagi_id!` with
/// `uuid = v4` or `uuid = v7`, which also adds the version's constructors
pub trait FeagiUuidID: FeagiID<16, DeserializationError = UuidVersionError> {
    /// The only UUID version this ID holds
    const VERSION: uuid::Version;

    /// Read this ID as a UUID
    fn as_uuid(&self) -> uuid::Uuid {
        uuid::Uuid::from_bytes(*self.get_id_bytes())
    }

    /// Wrap `uuid` when its version is [`FeagiUuidID::VERSION`]
    fn try_from_uuid(uuid: uuid::Uuid) -> Result<Self, UuidVersionError> {
        Self::try_from_id_bytes(uuid.into_bytes())
    }
}

/// Check that `bytes` are a UUID of `expected` version. Used as the check of the code
/// `feagi_id!` generates
#[doc(hidden)]
pub const fn check_uuid_version(bytes: &[u8; 16], expected: uuid::Version) -> Result<(), UuidVersionError> {
    let actual = uuid::Uuid::from_bytes(*bytes).get_version();
    match actual {
        // `Version` has no const `PartialEq`, so compare by number
        Some(version) if version as u8 == expected as u8 => Ok(()),
        _ => Err(UuidVersionError { expected, actual }),
    }
}

/// The bytes of a [`FeagiUuidID`] were not a UUID of the version that ID holds
#[derive(Debug, Error)]
#[error("UUID version {actual:?} did not match expected version {expected:?}")]
pub struct UuidVersionError {
    pub expected: uuid::Version,
    pub actual: Option<uuid::Version>,
}
